<script setup lang="ts">const{overview,pending,error,loadOverview}=useAccount();useHead({title:"هفت‌سوی من — هفت‌سو",meta:[{name:"robots",content:"noindex,nofollow"}]});onMounted(()=>void loadOverview());const stats=computed(()=>overview.value?[{label:"آگهی‌های من",value:overview.value.summary.posts,to:"/my/posts"},{label:"نشان‌ها",value:overview.value.summary.bookmarks,to:"/my/bookmarks"},{label:"بازدیدهای اخیر",value:overview.value.summary.recent,to:"/my/recent"},{label:"جست‌وجوهای ذخیره‌شده",value:overview.value.summary.savedSearches,to:"/my/saved-searches"}]:[]);</script>
<template><AccountShell title="نمای کلی حساب" description="محتوا، ترجیحات و امنیت حساب خود را یکجا مدیریت کنید."><UiState v-if="pending&&!overview" kind="loading" title="در حال دریافت حساب" description="اطلاعات حساب در حال بارگذاری است."/><p v-else-if="error" class="inline-error" role="alert">{{error}}</p><template v-else-if="overview"><section class="account-welcome"><div class="account-avatar">{{overview.profile.display_name.slice(0,1)}}</div><div><h2>{{overview.profile.display_name}}</h2><p>{{overview.profile.phone_masked}}</p></div><NuxtLink class="button button-secondary" to="/my/profile">ویرایش پروفایل</NuxtLink></section><div class="account-stat-grid"><NuxtLink v-for="stat in stats" :key="stat.to" :to="stat.to"><strong>{{stat.value.toLocaleString('fa-IR')}}</strong><span>{{stat.label}}</span></NuxtLink></div><IdentityStatusCard :status="overview.profile.identity_status"/></template></AccountShell></template>
